const body = $json.body ?? $json;
const items = Array.isArray(body.items) ? body.items : [];
const supportedFlows = new Set(['review', 'compliance', 'document', 'tests']);
if (items.length === 0) throw new Error('O campo items deve conter ao menos um item.');
const continueOnError = body.continue_on_error !== false;
const notify = body.notify === true;
const startedAtMs = Date.now();
function createUuid() { return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => { const random = Math.floor(Math.random() * 16); const value = character === 'x' ? random : ((random & 0x3) | 0x8); return value.toString(16); }); }
const batchId = createUuid();
function assertNonEmpty(value, field, index) { if (typeof value !== 'string' || !value.trim()) throw new Error(`Item ${index}: o campo ${field} e obrigatorio.`); }
function validatePayload(flowType, payload, index) { if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error(`Item ${index}: payload invalido.`); assertNonEmpty(payload.code, 'code', index); assertNonEmpty(payload.language, 'language', index); if (flowType === 'compliance') assertNonEmpty(payload.task_description, 'task_description', index); if (flowType === 'document' && !['technical', 'operational'].includes(String(payload.doc_type ?? '').trim())) throw new Error(`Item ${index}: doc_type deve ser technical ou operational.`); if (flowType === 'tests') assertNonEmpty(payload.test_framework, 'test_framework', index); }
const preparedItems = items.map((item, index) => { const flowType = String(item?.flow_type ?? '').trim(); if (!supportedFlows.has(flowType)) throw new Error(`Item ${index}: flow_type nao suportado: ${flowType || '(vazio)'}.`); validatePayload(flowType, item.payload, index); return { index, flow_type: flowType, payload: item.payload, endpoint: `/webhook/api/v1/${flowType}`, batch_id: batchId, started_at_ms: startedAtMs, continue_on_error: continueOnError, notify }; });
return [{ json: { batch_id: batchId, started_at_ms: startedAtMs, continue_on_error: continueOnError, notify, total_items: preparedItems.length, prepared_items: preparedItems } }];

