const prepared = $('Prepare Batch Request').first().json;
if (!Array.isArray(prepared.prepared_items) || prepared.prepared_items.length === 0) throw new Error('Batch items were not prepared.');
return prepared.prepared_items.map((item) => ({ json: item }));

const original = $('Loop Over Batch Items').first().json;
const response = $json;
const statusCode = Number(response.statusCode ?? response.status ?? 200);
const responseBody = response.body ?? response;
const success = statusCode >= 200 && statusCode < 300;
const errorMessage = success ? null : String(responseBody?.message ?? responseBody?.error ?? `HTTP ${statusCode}`);
return [{ json: { index: original.index, flow_type: original.flow_type, execution_id: null, status: success ? 'success' : 'failed', cache_hit: null, output: success ? responseBody : null, error_message: errorMessage, batch_id: original.batch_id, started_at_ms: original.started_at_ms, continue_on_error: original.continue_on_error, notify: original.notify } }];

const results = $('Normalize Batch Item Result').all().map((item) => item.json).sort((a, b) => a.index - b.index);
const prepared = $('Prepare Batch Request').first().json;
const successCount = results.filter((result) => result.status === 'success').length;
const failedCount = results.filter((result) => result.status === 'failed').length;
const status = failedCount === 0 ? 'success' : successCount === 0 ? 'failed' : 'partial';
const durationMs = Math.max(0, Date.now() - Number(prepared.started_at_ms));
function sql(value) { return String(value).replaceAll("'", "''"); }
const summaryQuery = `INSERT INTO batch_executions (id, status, item_count, success_count, failed_count, duration_ms)\nVALUES ('${sql(prepared.batch_id)}'::uuid, '${sql(status)}', ${prepared.total_items}, ${successCount}, ${failedCount}, ${durationMs})\nON CONFLICT (id) DO UPDATE SET status = EXCLUDED.status, item_count = EXCLUDED.item_count, success_count = EXCLUDED.success_count, failed_count = EXCLUDED.failed_count, duration_ms = EXCLUDED.duration_ms\nRETURNING id::text AS batch_id, '${sql(status)}' AS status, '${sql(JSON.stringify(results))}'::jsonb AS results;`;
return [{ json: { persist_batch_summary_query: summaryQuery } }];
